from z3 import *
import itertools

n = 12

# Create variables
X = [[Int(f'x_{i}_{j}') for j in range(n)] for i in range(n)]

s = Solver()

# Domain constraints
for i in range(n):
    for j in range(n):
        s.add(And(X[i][j] >= 0, X[i][j] < n))

# Latin square: rows and columns are permutations
for i in range(n):
    s.add(Distinct([X[i][j] for j in range(n)]))
for j in range(n):
    s.add(Distinct([X[i][j] for i in range(n)]))

# Idempotence
for i in range(n):
    s.add(X[i][i] == i)

# QG3: x[x[i][j]][x[j][i]] = i
# Encode as: for all i,j,k,l: if X[i][j]==k and X[j][i]==l then X[k][l]==i
for i in range(n):
    for j in range(n):
        for k in range(n):
            for l in range(n):
                s.add(Implies(And(X[i][j] == k, X[j][i] == l), X[k][l] == i))

print("Solving...")
result = s.check()
print(result)
if result == sat:
    m = s.model()
    grid = [[m.evaluate(X[i][j]).as_long() for j in range(n)] for i in range(n)]
    for row in grid:
        print(row)
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print("Flat:", flat)
else:
    print("UNSAT")

