# Let's search for QG3 idempotent quasigroups of small orders using brute force with Z3
from z3 import *

def find_qg3(n, timeout=30):
    f = Function('f', IntSort(), IntSort(), IntSort())
    s = Solver()

    for i in range(n):
        for j in range(n):
            s.add(And(f(i,j) >= 0, f(i,j) < n))

    for i in range(n):
        s.add(Distinct([f(i,j) for j in range(n)]))
    for j in range(n):
        s.add(Distinct([f(i,j) for i in range(n)]))

    for i in range(n):
        s.add(f(i,i) == i)

    for i in range(n):
        for j in range(n):
            s.add(f(f(i,j), f(j,i)) == i)

    s.set("timeout", timeout * 1000)
    result = s.check()
    if result == sat:
        m = s.model()
        grid = [[m.evaluate(f(i,j)).as_long() for j in range(n)] for i in range(n)]
        return grid
    return None

for n in [1, 2, 3, 4, 5, 6, 7, 8]:
    print(f"n={n}: ", end="")
    grid = find_qg3(n, timeout=10)
    if grid:
        print("SAT")
        for row in grid:
            print(" ", row)
    else:
        print("UNSAT or timeout")

